func (r *ResourceF5XCUser) Delete(ctx context.Context, request resource.DeleteRequest, response *resource.DeleteResponse) {
	var data ResourceF5XCUserModel

	// Read Terraform prior state data into the model
	response.Diagnostics.Append(request.State.Get(ctx, &data)...)
	if response.Diagnostics.HasError() {
		return
	}

	duration, err := time.ParseDuration("10m0s")
	if err != nil {
		response.Diagnostics.AddError(
			"Invalid Duration Format",
			fmt.Sprintf("Could not parse 'timeout' value %q: %s. "+
				"Please use a valid Go duration string like '10m', '1h30m' or '30s'.",
				"10m0s", err.Error()),
		)
		return
	}

	deleteTimeout, diags := data.Timeouts.Delete(ctx, duration)
	response.Diagnostics.Append(diags...)
	if response.Diagnostics.HasError() {
		return
	}

	ctx, cancel := context.WithTimeout(ctx, deleteTimeout)
	defer cancel()

	// CustomAPI Delete: CascadeDelete
	customDeleteRPCFQN := "ves.io.schema.user.CustomAPI.CascadeDelete"

	customDeleteURI := fmt.Sprintf("/public/custom/namespaces/%s/users/cascade_delete", data.Namespace.ValueString())
	// Build delete request body: primary key is a body field, not a URI path parameter.
	deleteReqBodyMap := map[string]interface{}{
		"email": data.Email.ValueString(),
	}
	deleteReqBodyBytes, err := json.Marshal(deleteReqBodyMap)
	if err != nil {
		response.Diagnostics.AddError(
			"Client Error", fmt.Sprintf("Unable to marshal delete request body for %s: %s", "user", err),
		)
		return
	}
	_, err = r.client.CustomAPI(ctx, "POST", customDeleteURI, customDeleteRPCFQN, string(deleteReqBodyBytes))
	if err != nil {
		if strings.Contains(err.Error(), "status code 404") {
			response.Diagnostics.AddError(
				"Client Error", fmt.Sprintf("Unable to delete %s, got error: %s", "user", err),
			)
			return
		}
	}

	// needed for eywa to sync with akar
	time.Sleep(5 * time.Millisecond)

	if err != nil {
		if strings.Contains(err.Error(), "status code 404") || strings.Contains(err.Error(), "NotFound") {
			// Object already gone, Terraform take it easy
			return
		}

		response.Diagnostics.AddError(
			"Client Error", fmt.Sprintf("Unable to delete %s, got error: %s", "user", err),
		)
		return
	}

}
func (r *ResourceF5XCUser) ImportState(ctx context.Context, req resource.ImportStateRequest, response *resource.ImportStateResponse) {
	// Import ID format: namespace/email
	parts := strings.Split(req.ID, "/")
	if len(parts) != 2 {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/email, got: %s", req.ID),
		)
		return
	}
	if parts[0] == "" {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/email, got: %s (namespace is empty)", req.ID),
		)
		return
	}
	response.Diagnostics.Append(response.State.SetAttribute(ctx, path.Root("namespace"), parts[0])...)
	if parts[1] == "" {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/email, got: %s (email is empty)", req.ID),
		)
		return
	}
	response.Diagnostics.Append(response.State.SetAttribute(ctx, path.Root("email"), parts[1])...)
}
